@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes in this category yet. <a href="/submit">Be the first to add one!</a></div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">
                                <a href="/recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                            </h4>
                            <p class="text-warning mb-1">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                                <span class="text-muted ms-2">(@recipe.AverageRating.ToString("F1")) · @recipe.RatingCount ratings</span>
                            </p>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        // Capitalize the first letter for display and lookup
        CategoryName = char.ToUpper(CategoryName[0]) + CategoryName[1..];
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1 class="mb-3">@Recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@Recipe.Category</span>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">🥕 Ingredients</h5></div>
            <div class="card-body">
                <ul class="list-unstyled mb-0">
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n'))
                    {
                        <li>• @ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
            <div class="card-body">
                @foreach (var step in Recipe.Steps.Split('\n'))
                {
                    <p class="mb-2">@step</p>
                }
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">⭐ Rating</h5></div>
            <div class="card-body">
                <p class="text-muted mb-2">Average: @Recipe.AverageRating.ToString("F1") / 5 (@Recipe.RatingCount ratings)</p>
                <StarRating RecipeId="@Recipe.Id" @rendermode="InteractiveServer" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<div>
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button"
                  class="@(star <= SelectedRating ? "text-warning" : "text-muted")"
                  style="cursor: pointer;"
                  @onclick="() => Rate(star)">★</span>
        }
    </span>

    @if (Submitted)
    {
        <span class="ms-2 text-success">✓ Rated @SelectedRating star@(SelectedRating != 1 ? "s" : "")!</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click to rate</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        Submitted = true;
        RecipeService.RateRecipe(RecipeId, stars);
    }
}

@page "/submit"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@rendermode InteractiveServer

@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit Recipe - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@Title</strong>" has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <div class="card shadow-sm">
            <div class="card-body">
                <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                    <div class="mb-3">
                        <label for="title" class="form-label">Recipe Title</label>
                        <InputText id="title" class="form-control" @bind-Value="Title" placeholder="e.g., Grandma's Apple Pie" />
                    </div>

                    <div class="mb-3">
                        <label for="category" class="form-label">Category</label>
                        <InputSelect id="category" class="form-select" @bind-Value="SelectedCategory">
                            <option value="">-- Select a category --</option>
                            @foreach (var cat in RecipeService.GetCategories())
                            {
                                <option value="@cat.Name">@cat.Name</option>
                            }
                        </InputSelect>
                    </div>

                    <div class="mb-3">
                        <label for="ingredients" class="form-label">Ingredients</label>
                        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Ingredients"
                            placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar" />
                    </div>

                    <div class="mb-3">
                        <label for="steps" class="form-label">Steps</label>
                        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Steps"
                            placeholder="One step per line&#10;e.g.,&#10;1. Preheat oven to 350°F&#10;2. Mix dry ingredients" />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg"
                            disabled="@(!IsFormValid)">Submit Recipe</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    private string Title { get; set; } = string.Empty;
    private string SelectedCategory { get; set; } = string.Empty;
    private string Ingredients { get; set; } = string.Empty;
    private string Steps { get; set; } = string.Empty;
    private bool IsSubmitted { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(Title) &&
        !string.IsNullOrWhiteSpace(SelectedCategory) &&
        !string.IsNullOrWhiteSpace(Ingredients) &&
        !string.IsNullOrWhiteSpace(Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;

        var recipe = new Recipe
        {
            Title = Title,
            Category = SelectedCategory,
            Ingredients = Ingredients,
            Steps = Steps,
            AverageRating = 0,
            RatingCount = 0
        };

        RecipeService.AddRecipe(recipe);
        IsSubmitted = true;
    }
}

